mapper.sql:
FROM ecom_package p
JOIN ecom_store s ON s.id = p.store_id
LEFT JOIN ecom_logistics_channel ch ON ch.id = p.channel_id
LEFT JOIN wms_warehouse w ON w.id = p.warehouse_id
WHERE p.status = 'SHIPPED'
AND p.store_id = #{q.storeId}
AND p.channel_id = #{q.channelId}
AND p.ship_country = #{q.country}
AND p.ship_time >= #{q.beginTime}
AND p.ship_time < #{q.endExclusive}

    AND (p.package_no LIKE CONCAT('%', #{q.keyword}, '%') OR p.tracking_no LIKE CONCAT('%', #{q.keyword}, '%')
         OR p.ship_name LIKE CONCAT('%', #{q.keyword}, '%')
         OR EXISTS (SELECT 1 FROM ecom_package_item pi JOIN ecom_order o ON o.id = pi.order_id
                    WHERE pi.package_id = p.id AND o.platform_order_no LIKE CONCAT('%', #{q.keyword}, '%')))

mapper.select:
SELECT p.id, p.package_no, p.store_id, p.warehouse_id, p.channel_id, p.carrier, p.carrier_name, p.tracking_no, p.status, p.ship_time, p.ship_name, p.ship_country, p.weight, p.shipping_cost, p.track_status, p.track_alert, p.track_source, p.track_first_time, p.track_last_time, p.track_last_event, p.track_delivered_time, p.track_pull_time, p.track_error, p.ship_confirm, p.ship_confirm_msg, p.create_time, p.update_time, s.name AS store_name, ch.name AS channel_name, w.name AS warehouse_name, (SELECT MIN(o.platform_order_no) FROM ecom_package_item pi JOIN ecom_order o ON o.id = pi.order_id WHERE pi.package_id = p.id) AS order_nos, (SELECT COUNT(DISTINCT pi.order_id) FROM ecom_package_item pi WHERE pi.package_id = p.id) AS order_count
AND (p.track_status IS NULL OR p.track_status = 'NOT_FOUND') AND p.track_status = #{q.trackStatus}
AND p.track_alert = #{q.alert} AND p.track_alert IS NOT NULL ORDER BY p.ship_time DESC, p.id DESC

SELECT p.id FROM ecom_package p
WHERE p.status = 'SHIPPED' AND p.tracking_no IS NOT NULL AND p.ship_time >= #{shippedAfter}
  AND (p.track_status IS NULL OR p.track_status NOT IN ('DELIVERED', 'RETURNED'))
  AND (p.track_pull_time IS NULL OR p.track_pull_time < #{pulledBefore})
ORDER BY p.track_pull_time, p.id
LIMIT #{limit}
